import Foundation
import CoreGraphics
import ImageIO

// The cat bitmaps are regenerated by scripts/render_cats.py. This checks
// that what is in the asset catalog still fits the layout that draws it:
// canvas proportions, both scales, and the tail staying clear of the
// first candidate.

private func expect(_ condition: Bool, _ message: @autoclosure () -> String, line: UInt = #line) {
    if !condition {
        print("FAIL: \(message()) (CatArtTests.swift:\(line))")
        exit(1)
    }
}

struct Bitmap {
    var width: Int
    var height: Int
    var alpha: [UInt8]

    init?(_ url: URL) {
        guard let source = CGImageSourceCreateWithURL(url as CFURL, nil),
              let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return nil }
        let columns = image.width, rows = image.height
        var pixels = [UInt8](repeating: 0, count: columns * rows * 4)
        let drawn = pixels.withUnsafeMutableBytes { buffer -> Bool in
            guard let context = CGContext(data: buffer.baseAddress, width: columns, height: rows, bitsPerComponent: 8,
                                          bytesPerRow: columns * 4, space: CGColorSpaceCreateDeviceRGB(),
                                          bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return false }
            context.draw(image, in: CGRect(x: 0, y: 0, width: columns, height: rows))
            return true
        }
        guard drawn else { return nil }
        width = columns
        height = rows
        alpha = stride(from: 3, to: pixels.count, by: 4).map { pixels[$0] }
    }

    /// Alpha at a point given as fractions of the canvas, origin top left.
    func alpha(x: CGFloat, y: CGFloat) -> UInt8 {
        let column = min(width - 1, max(0, Int(x * CGFloat(width))))
        let row = min(height - 1, max(0, Int(y * CGFloat(height))))
        return alpha[row * width + column]
    }
}

@main
struct CatArtTests {
    static let catalog = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("Keyboard/Cats.xcassets")

    static func load(_ name: String, scale: Int) -> Bitmap {
        let url = catalog.appendingPathComponent("\(name).imageset/\(name)@\(scale)x.png")
        guard let bitmap = Bitmap(url) else {
            print("FAIL: cannot read \(url.path)")
            exit(1)
        }
        return bitmap
    }

    static func main() {
        let frames = ["open", "happy", "blink"]
        for (cat, aspect) in [("mimimo", CandidateRegionLayout.mimimoAspect), ("momo", CandidateRegionLayout.momoAspect)] {
            let sizes = frames.map { frame -> (Int, Int) in
                let large = load("\(cat)_\(frame)", scale: 3), small = load("\(cat)_\(frame)", scale: 2)
                expect(abs(CGFloat(large.width) / CGFloat(large.height) - aspect) < 0.012, "\(cat)_\(frame) canvas is \(large.width)×\(large.height), layout expects \(aspect)")
                expect(abs(CGFloat(small.width) * 1.5 - CGFloat(large.width)) <= 2 && abs(CGFloat(small.height) * 1.5 - CGFloat(large.height)) <= 2,
                       "\(cat)_\(frame) @2x and @3x are the same picture")
                expect(large.alpha.contains { $0 > 250 } && large.alpha.contains { $0 == 0 }, "\(cat)_\(frame) has a transparent background")
                return (large.width, large.height)
            }
            expect(sizes.allSatisfy { $0 == sizes[0] }, "\(cat) frames share one canvas, so expressions swap in place")
            // Enough pixels for the largest size it is drawn at: the widest
            // phones at 3x and the iPad at 2x.
            let small = load("\(cat)_open", scale: 2)
            for (idiom, width, scale, rows) in [(KeyboardIdiom.phone, CGFloat(466), CGFloat(3), sizes[0].1), (.pad, 820, 2, small.height)] {
                let layout = CandidateRegionLayout(width: width, idiom: idiom)
                let drawn = cat == "mimimo" ? layout.mimimo.height : layout.momo.height
                expect(CGFloat(rows) >= drawn * scale - 1, "\(cat) @\(Int(scale))x has at least \(Int(drawn * scale)) rows for \(idiom) at \(Int(width)) pt (has \(rows))")
            }
        }

        let tail = load("mimimo_tail", scale: 3)
        expect(abs(CGFloat(tail.width) / CGFloat(tail.height) - CandidateRegionLayout.tailAspect) < 0.05, "tail canvas is \(tail.width)×\(tail.height)")
        _ = load("mimimo_tail", scale: 2)

        // The tail runs in front of the glass. Where candidates are drawn it
        // must stay under the selected capsule, on every phone width, in
        // landscape and on an iPad.
        let cases: [(KeyboardIdiom, CGFloat)] = [(.phone, 320), (.phone, 375), (.phone, 393), (.phone, 402), (.phone, 430), (.phone, 440),
                                                 (.phone, 466), (.phoneLandscape, 720), (.pad, 820)]
        for (idiom, width) in cases {
            let layout = CandidateRegionLayout(width: width, idiom: idiom)
            // The first capsule starts 2 pt into the row (the strip's inset)
            // and its left end is round.
            let capsuleLeft = layout.row.minX + 2, radius = layout.pillHeight / 2
            func capsuleBottom(_ x: CGFloat) -> CGFloat {
                let dx = min(radius, x - capsuleLeft)
                return layout.glass.midY + (radius * radius - (radius - dx) * (radius - dx)).squareRoot()
            }
            var x = max(capsuleLeft, layout.tail.minX)
            while x < layout.tail.maxX {
                var y = layout.tail.minY
                while y < layout.tail.maxY {
                    if tail.alpha(x: (x - layout.tail.minX) / layout.tail.width, y: (y - layout.tail.minY) / layout.tail.height) > 96 {
                        expect(y >= capsuleBottom(x) + 0.5,
                               "at \(width) pt (\(idiom)) the tail reaches y=\(y) at x=\(x); the selected capsule ends at \(capsuleBottom(x))")
                        break
                    }
                    y += 0.25
                }
                x += 0.25
            }
            // Its root is at 米米莫's side, left of the candidates.
            var rootFound = false
            var rx = layout.tail.minX
            while rx < layout.row.minX && !rootFound {
                var y = layout.tail.minY
                while y < layout.tail.maxY {
                    if tail.alpha(x: (rx - layout.tail.minX) / layout.tail.width, y: (y - layout.tail.minY) / layout.tail.height) > 96 { rootFound = true; break }
                    y += 0.5
                }
                rx += 0.5
            }
            expect(rootFound, "the tail starts beside 米米莫 at \(width) pt")
        }

        // The expand key tucks under 莫莫's chin without her covering its glyph,
        // for every glass shape (the rim moves her down).
        let momo = load("momo_open", scale: 3)
        for (idiom, width) in cases {
            for rim: CGFloat in [0, 0.065, 0.16] {
                let layout = CandidateRegionLayout(width: width, idiom: idiom, rim: rim)
                let glyph = CGRect(x: layout.chevron.midX - CandidateRegionLayout.chevronGlyph.width / 2,
                                   y: layout.chevron.midY - CandidateRegionLayout.chevronGlyph.height / 2,
                                   width: CandidateRegionLayout.chevronGlyph.width, height: CandidateRegionLayout.chevronGlyph.height)
                var y = max(glyph.minY, layout.momo.minY)
                while y < min(glyph.maxY, layout.momo.maxY) {
                    var x = max(glyph.minX, layout.momo.minX)
                    while x < glyph.maxX + 1 {
                        expect(momo.alpha(x: (x - layout.momo.minX) / layout.momo.width, y: (y - layout.momo.minY) / layout.momo.height) < 40,
                               "at \(width) pt (\(idiom), rim \(rim)) 莫莫 covers the expand key at x=\(x) y=\(y)")
                        x += 0.25
                    }
                    y += 0.25
                }
            }
        }
        print("PASS: cat canvases match the layout, both scales are present, the tail stays under the candidates, 莫莫 leaves the expand key clear")
    }
}
